// Word's built-in table styles, as Word for Mac 16 writes them into styles.xml
// once a table uses one (probe 2026-11-23: each style applied to a table of a
// document without a theme, then the saved definitions copied verbatim, rsids
// dropped). Colors carry Word's w:themeColor next to the Office theme hex.

export type BuiltInTableStyleGroup = 'plain' | 'grid' | 'list'

export interface BuiltInTableStyle {
  styleId: string
  name: string
  group: BuiltInTableStyleGroup
  /** the w:style element as Word writes it */
  xml: string
}

/** Word's default table style, the base every built-in table style names */
export const BUILT_IN_TABLE_NORMAL_XML =
  '<w:style w:type="table" w:default="1" w:styleId="TableNormal"><w:name w:val="Normal Table"/>' +
  '<w:uiPriority w:val="99"/><w:semiHidden/><w:unhideWhenUsed/><w:tblPr><w:tblInd w:w="0" w:type="dxa"/>' +
  '<w:tblCellMar><w:top w:w="0" w:type="dxa"/><w:left w:w="108" w:type="dxa"/>' +
  '<w:bottom w:w="0" w:type="dxa"/><w:right w:w="108" w:type="dxa"/></w:tblCellMar></w:tblPr></w:style>'

